const API=`https://api.jsonbin.io/v3/b/${BIN_ID}`;
const SESSION='SA_SESSION_V100';
const LOGO_DATA='data:image/png;base64,';
let S=JSON.parse(sessionStorage.getItem(SESSION)||'null');
const LESSONS=window.SA_LESSONS||[];
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function save(){sessionStorage.setItem(SESSION,JSON.stringify(S))}
function gate(){if(!S){location.href='index.html';return false}return true}
function mastery(){return Math.round(Object.keys(S.progress||{}).length/365*100)}
function level(){let m=mastery();return m>=100?'Supreme Avatar':m>=90?'Master':m>=75?'Expert':m>=60?'Scholar':m>=45?'Strategist':m>=30?'Critical Thinker':m>=15?'Analyst':'Novice'}
function nav(a){return `<header><div class="shell nav"><a class="brand" href="dashboard.html"><img class="brand-logo" src="${LOGO_DATA}" alt="Supreme Avatars logo"><span>SUPREME AVATARS</span></a><nav>${['dashboard','study','roadmap','labs','strategy','journal','profile'].map(x=>`<a class="${a===x?'active':''}" href="${x}.html">${x[0].toUpperCase()+x.slice(1)}</a>`).join('')}</nav><span class="pill">${S?esc(S.name):'Guest'}</span></div></header>`}
function layout(a,b){document.body.innerHTML=nav(a)+`<main class="shell">${b}</main><footer>SUPREME AVATARS • 365-DAY ACADEMY • Multidimensional mastery, not fake IQ claims.</footer>`}
async function readBin(){let r=await fetch(API+'/latest',{headers:{'X-Access-Key':ACCESS_KEY}});if(!r.ok)throw Error('JSONBin read failed: '+r.status);return (await r.json()).record||{users:{}}}
async function writeBin(record){let r=await fetch(API,{method:'PUT',headers:{'Content-Type':'application/json','X-Access-Key':ACCESS_KEY,'X-Bin-Versioning':'true'},body:JSON.stringify(record)});if(!r.ok)throw Error('JSONBin write failed: '+r.status);return r.json()}
async function hash(p,s){let b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s+'|'+p));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function salt(){return crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random()}
